import {
    AttachRolePolicyCommand,
    CreatePolicyCommand,
    CreateRoleCommand,
    IAMClient,
    UpdateAssumeRolePolicyCommand,
} from '@aws-sdk/client-iam';
import { BadRequestException, Logger } from '@nestjs/common';

const logger = new Logger('IAMUtils');

export const DEFAULT_AWS_REGION = 'us-east-1';

/**
 * The maximum length AWS allows for an IAM role or policy name.
 */
const MAX_IAM_NAME_LENGTH = 64;

/**
 * IAM role and policy names only support a limited set of characters,
 * `businessID`s and other identifiers may contain characters outside of that set.
 */
export const sanitizeIAMName = (name: string): string =>
    `${name || ''}`
        .replace(/[^\w+=,.@-]/g, '-')
        .replace(/-{2,}/g, '-')
        .replace(/^-|-$/g, '');

/**
 * Builds a unique, deterministic-per-measurement name for the IAM resources created for a customer.
 */
export const buildUniqueIAMName = (prefix: string, ...parts: Array<string>): string => {
    const name = [prefix, ...parts.filter((part) => part !== undefined && part !== null && `${part}` !== '')]
        .map((part) => sanitizeIAMName(`${part}`))
        .filter((part) => part.length)
        .join('-');
    return name.length > MAX_IAM_NAME_LENGTH ? name.slice(0, MAX_IAM_NAME_LENGTH) : name;
};

export const getIAMClient = (region: string = DEFAULT_AWS_REGION) => new IAMClient({ region });

/**
 * The trust relationship allowing a customer's AWS account to assume the Paigo owned role.
 * The `externalId` protects against the confused deputy problem.
 */
export const buildAssumeRolePolicyDocument = (accountId: string, externalId: string) => ({
    Version: '2012-10-17',
    Statement: [
        {
            Sid: 'PaigoDatastoreAccess',
            Effect: 'Allow',
            Principal: {
                AWS: `arn:aws:iam::${accountId}:root`,
            },
            Action: 'sts:AssumeRole',
            Condition: {
                StringEquals: {
                    'sts:ExternalId': externalId,
                },
            },
        },
    ],
});

/**
 * The permissions granted to the customer.
 * Write access is granted on the ingestion prefix and read access on the DLQ prefix.
 * Both are scoped down to the prefix owned by the business creating the measurement.
 */
export const buildDatastorePolicyDocument = ({
    ingestionBucket,
    dlqBucket,
    prefix,
}: {
    ingestionBucket: string;
    dlqBucket: string;
    prefix: string;
}) => ({
    Version: '2012-10-17',
    Statement: [
        {
            Sid: 'PaigoUsageIngestion',
            Effect: 'Allow',
            Action: ['s3:PutObject', 's3:GetObject', 's3:AbortMultipartUpload'],
            Resource: [`arn:aws:s3:::${ingestionBucket}/${prefix}/*`],
        },
        {
            Sid: 'PaigoUsageDeadLetterQueue',
            Effect: 'Allow',
            Action: ['s3:GetObject'],
            Resource: [`arn:aws:s3:::${dlqBucket}/${prefix}/*`],
        },
        {
            Sid: 'PaigoUsageListPrefixes',
            Effect: 'Allow',
            Action: ['s3:ListBucket'],
            Resource: [`arn:aws:s3:::${ingestionBucket}`, `arn:aws:s3:::${dlqBucket}`],
            Condition: {
                StringLike: {
                    's3:prefix': [`${prefix}/*`],
                },
            },
        },
    ],
});

export const getRoleNameFromArn = (iamRoleArn: string): string => {
    if (!iamRoleArn) {
        return undefined;
    }
    const [, roleName] = `${iamRoleArn}`.split(':role/');
    return roleName ? roleName.split('/').pop() : undefined;
};

/**
 * Creates the role, the policy scoped to the business prefixes and attaches them together.
 *
 * @returns the ARN of the newly created role
 */
export const createDatastoreAccessRole = async ({
    roleName,
    policyName,
    accountId,
    externalId,
    ingestionBucket,
    dlqBucket,
    prefix,
    region = DEFAULT_AWS_REGION,
    description,
}: {
    roleName: string;
    policyName: string;
    accountId: string;
    externalId: string;
    ingestionBucket: string;
    dlqBucket: string;
    prefix: string;
    region?: string;
    description?: string;
}): Promise<string> => {
    const client = getIAMClient(region);
    try {
        const { Role } = await client.send(
            new CreateRoleCommand({
                RoleName: roleName,
                Description: description,
                AssumeRolePolicyDocument: JSON.stringify(buildAssumeRolePolicyDocument(accountId, externalId)),
            })
        );

        const { Policy } = await client.send(
            new CreatePolicyCommand({
                PolicyName: policyName,
                PolicyDocument: JSON.stringify(
                    buildDatastorePolicyDocument({ ingestionBucket, dlqBucket, prefix })
                ),
            })
        );

        await client.send(
            new AttachRolePolicyCommand({
                RoleName: roleName,
                PolicyArn: Policy?.Arn,
            })
        );

        return Role?.Arn;
    } catch (error) {
        logger.error(`Failed to provision datastore access for account ${accountId}`, error);
        throw translateIAMError(error, accountId);
    }
};

/**
 * Updates the trust relationship of an already provisioned role.
 * The role itself and the external ID are left untouched.
 */
export const updateDatastoreAccessRoleTrust = async ({
    iamRoleArn,
    accountId,
    externalId,
    region = DEFAULT_AWS_REGION,
}: {
    iamRoleArn: string;
    accountId: string;
    externalId: string;
    region?: string;
}): Promise<void> => {
    const roleName = getRoleNameFromArn(iamRoleArn);
    if (!roleName) {
        throw new BadRequestException(`Unable to determine the IAM role to update from: ${iamRoleArn}`);
    }
    const client = getIAMClient(region);
    try {
        await client.send(
            new UpdateAssumeRolePolicyCommand({
                RoleName: roleName,
                PolicyDocument: JSON.stringify(buildAssumeRolePolicyDocument(accountId, externalId)),
            })
        );
    } catch (error) {
        logger.error(`Failed to update datastore access for account ${accountId}`, error);
        throw translateIAMError(error, accountId);
    }
};

const translateIAMError = (error, accountId: string) => {
    const code = error?.Code || error?.name;
    if (code === 'MalformedPolicyDocument' || code === 'MalformedPolicyDocumentException') {
        return new BadRequestException(`AccountId: ${accountId} is invalid`);
    }
    return error;
};

import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { Upload } from '@aws-sdk/lib-storage';

export const DEFAULT_AWS_REGION = 'us-east-1';

/**
 * The bucket customers write their usage records into.
 */
export const DEFAULT_DATASTORE_INGESTION_BUCKET = 'paigo-usage-record-dump-bucket';

/**
 * The bucket unprocessable usage records get written to.
 */
export const DEFAULT_DATASTORE_DLQ_BUCKET = 'paigo-usage-record-dlq-bucket';

/**
 * Suffix appended to the mirrored source key of a record which failed processing.
 */
export const DLQ_KEY_SUFFIX = '.message.text';

export const getDatastoreIngestionBucket = (): string =>
    process.env.DB_MEASUREMENT_BUCKET_NAME || DEFAULT_DATASTORE_INGESTION_BUCKET;

export const getDatastoreDlqBucket = (): string =>
    process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME || DEFAULT_DATASTORE_DLQ_BUCKET;

export const putDocument = (document, Bucket, Key) =>
    new Upload({ client: new S3Client({ region: DEFAULT_AWS_REGION }), params: { Body: document, Bucket, Key } });

/**
 * Normalizes an S3 key so the returned value is always relative to its bucket.
 * Keys arriving from connectors can either be fully qualified (`s3://bucket/key`,
 * `arn:aws:s3:::bucket/key`, `bucket/key`) or already relative (`key`).
 *
 * @example toRelativeS3Key('s3://paigo-usage-record-dump-bucket/business/file.json') // 'business/file.json'
 * @example toRelativeS3Key('business/file.json') // 'business/file.json'
 */
export const toRelativeS3Key = (s3Key: string): string => {
    if (!s3Key) {
        return '';
    }
    let key = `${s3Key}`.trim();
    const schemes = ['s3://', 'arn:aws:s3:::', 'https://', 'http://'];
    const matchedScheme = schemes.find((scheme) => key.toLowerCase().startsWith(scheme));
    if (matchedScheme) {
        key = key.slice(matchedScheme.length);
        // The first segment of a fully qualified key is always the bucket
        key = key.split('/').slice(1).join('/');
    } else {
        key = key.replace(/^\/+/, '');
        // Handle the case where the bucket name is prefixed without a scheme
        const [firstSegment, ...rest] = key.split('/');
        if (rest.length && [getDatastoreIngestionBucket(), getDatastoreDlqBucket()].includes(firstSegment)) {
            key = rest.join('/');
        }
    }
    return key.replace(/^\/+/, '');
};

/**
 * Writes a document to S3.
 */
export const putObject = async ({
    Bucket,
    Key,
    Body,
    ContentType,
    region = DEFAULT_AWS_REGION,
}: {
    Bucket: string;
    Key: string;
    Body: string;
    ContentType?: string;
    region?: string;
}) => {
    const client = new S3Client({ region });
    return client.send(new PutObjectCommand({ Bucket, Key, Body, ContentType }));
};

/**
 * Writes a record which could not be processed to the dead letter queue.
 * The object is stored under the mirrored source key, suffixed with `.message.text`,
 * and holds both the failed input and the metadata of the failed processing attempt.
 */
export const writeToDeadLetterQueue = async ({
    s3Key,
    message,
    error,
    businessID,
    Bucket = getDatastoreDlqBucket(),
}: {
    s3Key: string;
    message?: unknown;
    error?: unknown;
    businessID?: string;
    Bucket?: string;
}) => {
    const relativeKey = toRelativeS3Key(s3Key);
    const Key = `${relativeKey}${DLQ_KEY_SUFFIX}`;
    const Body = JSON.stringify({
        message,
        s3Key,
        sourceKey: relativeKey,
        businessID,
        error: error instanceof Error ? error.message : error,
        failedAt: new Date().toISOString(),
    });
    await putObject({ Bucket, Key, Body, ContentType: 'text/plain' });
    return { Bucket, Key };
};

