export class DatastoreAccessInformation {
    /**
     * The datastore platform Paigo ingests the usage records from. Optional, default is `s3`.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        example: 's3',
    })
    public platform?: SupportedDatastores;

    /**
     * The unique ID of the cloud account which writes the usage records. Required.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '623673123435' })
    public accountId: string;

    /**
     *
     * The region of the datastore Paigo ingests the usage records from. Optional, default is `us-east-1`.
     *
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: DEFAULT_AWS_REGION })
    public region?: string;

    /**
     * READ ONLY. Generated by Paigo.
     * The IAM role the account identified by `accountId` can assume in order to write usage records
     * to the ingestion location and to read from the dead letter queue.
     * <br><br>
     * Example `"arn:aws:iam::214826386939:role/paigo-dev-datastore-de388932"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ readOnly: true, required: false })
    public iamRoleArn?: string;

    /**
     * READ ONLY. Generated by Paigo.
     * The external ID which must be provided when assuming the generated `iamRoleArn`.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ readOnly: true, required: false })
    public externalId?: string;

    /**
     * READ ONLY. Generated by Paigo.
     * The location usage records are written to.
     * <br><br>
     * Example `"s3://paigo-usage-record-dump-bucket/myBusiness"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ readOnly: true, required: false })
    public ingestion?: string;

    /**
     * READ ONLY. Generated by Paigo.
     * The location usage records which could not be processed are written to.
     * <br><br>
     * Example `"s3://paigo-usage-record-dlq-bucket/myBusiness"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ readOnly: true, required: false })
    public dlq?: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID?: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation) {
        if (datastoreAccessInformation) {
            const { accountId, platform, region, iamRoleArn, externalId, ingestion, dlq, businessID } =
                datastoreAccessInformation;
            this.platform = platform ? platform : SupportedDatastores.s3;
            this.accountId = accountId;
            this.region = region ? region : DEFAULT_AWS_REGION;
            if (iamRoleArn) {
                this.iamRoleArn = iamRoleArn;
            }
            if (externalId) {
                this.externalId = externalId;
            }
            this.businessID = businessID;
            this.ingestion = ingestion
                ? ingestion
                : DatastoreAccessInformation.buildLocation(getDatastoreIngestionBucket(), businessID);
            this.dlq = dlq ? dlq : DatastoreAccessInformation.buildLocation(getDatastoreDlqBucket(), businessID);
        }
    }

    /**
     * Builds the s3 URI of the prefix a business owns inside of one of the paigo owned buckets.
     */
    public static buildLocation(bucket: string, businessID: string): string {
        return businessID ? `s3://${bucket}/${businessID}` : `s3://${bucket}`;
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { platform, accountId, region, iamRoleArn, externalId, ingestion, dlq } =
                datastoreAccessInformation;
            if (platform) influxPoint.tag('platform', platform);
            if (accountId) influxPoint.tag('accountId', accountId);
            if (region) influxPoint.tag('region', region);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        accountId,
        region,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        businessID,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform,
            accountId,
            region,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            businessID,
        });
    }

    /**
     * Provisions the access needed by a customer to push usage records into Paigo.
     * A dedicated IAM role, and a policy scoped down to the prefixes owned by the business,
     * are created and the customers account is trusted with a freshly generated external ID.
     *
     * The `dbAccessInformation` is enriched in place with the generated values.
     */
    public static async setupAccess(
        dbAccessInformation: DatastoreAccessInformation,
        { measurementId }: { measurementId?: string } = {}
    ): Promise<DatastoreAccessInformation> {
        const { accountId, platform, region, businessID } = dbAccessInformation;
        if (platform && platform.toLowerCase() !== SupportedDatastores.s3) {
            return dbAccessInformation;
        }
        if (!accountId) {
            throw new BadRequestException('accountId is required for datastore based measurements');
        }
        // Preserve an already provisioned role, only the trust relationship needs to be refreshed
        if (dbAccessInformation.iamRoleArn) {
            await updateDatastoreAccessRoleTrust({
                iamRoleArn: dbAccessInformation.iamRoleArn,
                accountId,
                externalId: dbAccessInformation.externalId,
                region,
            });
            return dbAccessInformation;
        }

        const externalId = randomUUID();
        const uniqueSuffix = measurementId ? measurementId : randomUUID();
        const roleName = buildUniqueIAMName(
            `paigo-${process.env.STAGE ? process.env.STAGE : 'dev'}-datastore`,
            uniqueSuffix
        );
        const policyName = buildUniqueIAMName(
            `paigo-${process.env.STAGE ? process.env.STAGE : 'dev'}-datastore-policy`,
            uniqueSuffix
        );
        const ingestionBucket = getDatastoreIngestionBucket();
        const dlqBucket = getDatastoreDlqBucket();

        const iamRoleArn = await createDatastoreAccessRole({
            roleName,
            policyName,
            accountId,
            externalId,
            ingestionBucket,
            dlqBucket,
            prefix: businessID,
            region,
            description: `Usage record ingestion role for ${businessID}`,
        });

        dbAccessInformation.iamRoleArn = iamRoleArn;
        dbAccessInformation.externalId = externalId;
        dbAccessInformation.ingestion = DatastoreAccessInformation.buildLocation(ingestionBucket, businessID);
        dbAccessInformation.dlq = DatastoreAccessInformation.buildLocation(dlqBucket, businessID);

        return dbAccessInformation;
    }

    /**
     * Updates the access of an existing datastore measurement.
     * The generated role and external ID are preserved, only the trusted account can change.
     */
    public static async updateAccess(
        dbAccessInformation: DatastoreAccessInformation,
        { measurementId }: { measurementId?: string } = {}
    ): Promise<DatastoreAccessInformation> {
        const { accountId, iamRoleArn, externalId, region } = dbAccessInformation;
        if (!iamRoleArn) {
            // Nothing was provisioned yet, provision it now
            return DatastoreAccessInformation.setupAccess(dbAccessInformation, { measurementId });
        }
        await updateDatastoreAccessRoleTrust({ iamRoleArn, accountId, externalId, region });
        return dbAccessInformation;
    }
}

