/**
 * Removes the keys holding an `undefined` value from an object.
 * Useful when merging a partial update onto an already persisted document,
 * as unset keys should not wipe out the persisted values.
 */
export const removeUndefinedValues = <T extends Record<string, unknown>>(object: T): Partial<T> => {
    if (!object) {
        return {};
    }
    return Object.keys(object).reduce((accumulator, key) => {
        if (object[key] !== undefined) {
            accumulator[key] = object[key];
        }
        return accumulator;
    }, {} as Partial<T>);
};
