import { Body, Controller, Logger, Post, Req, UseGuards } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { ApiBadRequestResponse, ApiCreatedResponse, ApiOperation, ApiTags } from '@nestjs/swagger';
import { BasicResponseDTO } from '../basicResponseDTO';
import { CreateUsageDto } from './dto/create-usage.dto';
import { UsageService } from './usage.service';
import { Request } from 'express';
import { DbMeasuredusageDto } from './dto/dbmeasuredUsage.dto';
import { LogGaurd } from '../authz/logGaurd';
import { toRelativeS3Key, writeToDeadLetterQueue } from '../utils/aws/s3';

@ApiTags('Usage')
@Controller('usage')
export class UsageController {
    private static readonly logger = new Logger(UsageController.name);
    constructor(private readonly usageService: UsageService) {}

    /**
     * Collect usage data by API-based method.
     * See <a href="https://docs.paigo.tech/measure-usage-and-collect-data/measure-and-collect-usage-data-at-production-scale">Measure and Collect Usage Data At Production Scale</a>
     * for full documentation on Paigo <b>Usage Measurement and Collection</b>.
     * @param createUsageDto
     * @param request
     */
    @ApiCreatedResponse({
        status: 201,
        description: 'OK',
        type: BasicResponseDTO,
    })
    @ApiBadRequestResponse({
        status: 400,
        description: 'Bad Request',
        type: BasicResponseDTO,
    })
    @ApiOperation({ operationId: 'Collect usage data' })
    @UseGuards(AuthGuard('jwt'))
    @Post()
    create(@Body() createUsageDto: CreateUsageDto, @Req() request: Request) {
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID } = request.user;
        return this.usageService.create({ ...createUsageDto, businessID });
    }

    /**
     * Collect usage data gathered by the datastore based measurement method.
     * This endpoint is for internal use only, it is called by the connector reading
     * the usage records a customer dropped into their ingestion location.
     *
     * Records which cannot be processed are written to the dead letter queue
     * mirroring the key of the record which failed, so they can be reprocessed manually.
     */
    @UseGuards(LogGaurd, AuthGuard('jwt'))
    @Post('db')
    async dbUsage(@Body() createUsageDto: DbMeasuredusageDto) {
        // Custom validator for DB usage, on failure push to DLQ for manual processing

        UsageController.logger.log('Starting DB Usage Endpoint execution');

        const { message, s3Key } = createUsageDto ? createUsageDto : ({} as DbMeasuredusageDto);
        // TODO: check if the passed in BusinessID is an authorized producer, if not throw message away
        try {
            if (!s3Key) {
                throw new Error('No s3Key was provided with the usage record');
            }
            // The key can arrive fully qualified, the first segment of the relative key is the businessID
            const sourceKey = toRelativeS3Key(s3Key);
            const [businessID] = sourceKey.split('/');
            if (!businessID) {
                throw new Error(`Unable to determine the businessID from the s3Key: ${s3Key}`);
            }
            const parsed = UsageController.parseUsageRecord(message);
            const input = { ...parsed, businessID };
            return await this.usageService.create(input);
        } catch (error) {
            UsageController.logger.error(
                `Failed to process usage record for key: ${s3Key}, writing it to the dead letter queue`,
                error
            );
            return UsageController.publishToDeadLetterQueue({ s3Key, message, error });
        }
    }

    /**
     * Parses a usage record collected from a datastore.
     * Throws when the record is not a processable standard usage record.
     */
    private static parseUsageRecord(message: unknown): CreateUsageDto {
        if (message === undefined || message === null || message === '') {
            throw new Error('No usage record was provided');
        }
        const parsed = typeof message === 'string' ? JSON.parse(message) : message;
        if (typeof parsed !== 'object' || Array.isArray(parsed) || parsed === null) {
            throw new Error('The usage record provided is not a valid usage record object');
        }
        if (parsed.recordValue === undefined || parsed.recordValue === null || parsed.recordValue === '') {
            throw new Error('The usage record provided is missing a recordValue');
        }
        if (!parsed.dimensionId) {
            throw new Error('The usage record provided is missing a dimensionId');
        }
        return parsed as CreateUsageDto;
    }

    /**
     * Writes a record which could not be processed to the dead letter queue,
     * mirroring the key of the source record.
     */
    private static async publishToDeadLetterQueue({
        s3Key,
        message,
        error,
    }: {
        s3Key: string;
        message: unknown;
        error: unknown;
    }) {
        const sourceKey = toRelativeS3Key(s3Key);
        const [businessID] = sourceKey.split('/');
        try {
            const { Bucket, Key } = await writeToDeadLetterQueue({
                s3Key: sourceKey ? sourceKey : 'unprocessable',
                message,
                error,
                businessID,
            });
            UsageController.logger.log(`Wrote unprocessable usage record to s3://${Bucket}/${Key}`);
            return { message: 'Usage record could not be processed, it was written to the dead letter queue' };
        } catch (dlqError) {
            UsageController.logger.error('Failed to write the unprocessable usage record to the dead letter queue', {
                s3Key,
                dlqError,
            });
            return { message: 'Usage record could not be processed' };
        }
    }
}

