import {
    AttachRolePolicyCommand,
    CreatePolicyCommand,
    CreateRoleCommand,
    IAMClient,
    UpdateAssumeRolePolicyCommand,
} from '@aws-sdk/client-iam';
import { mockClient } from 'aws-sdk-client-mock';
import { measurementMode } from '../dto/create-measurement-config.dto';
import {
    DatastoreAccessInformation,
    MeasurementConfigEntity,
    SupportedDatastores,
} from './measurement-config.entity';

const iamMock = mockClient(IAMClient);

describe('DatastoreAccessInformation', () => {
    const businessID = 'fakeBusiness';
    const accountId = '623673123435';

    beforeAll(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'paigo-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'paigo-usage-record-dlq-bucket';
    });

    beforeEach(() => {
        iamMock.reset();
        iamMock.on(CreateRoleCommand).callsFake(({ RoleName }) => ({
            Role: { Arn: `arn:aws:iam::647662420899:role/${RoleName}` },
        }));
        iamMock.on(CreatePolicyCommand).callsFake(({ PolicyName }) => ({
            Policy: { Arn: `arn:aws:iam::647662420899:policy/${PolicyName}` },
        }));
        iamMock.on(AttachRolePolicyCommand).resolves({});
        iamMock.on(UpdateAssumeRolePolicyCommand).resolves({});
    });

    it('defaults the platform to s3 and the region to us-east-1', () => {
        const configuration = new DatastoreAccessInformation({ accountId, businessID } as DatastoreAccessInformation);

        expect(configuration.platform).toEqual(SupportedDatastores.s3);
        expect(configuration.region).toEqual('us-east-1');
        expect(configuration.accountId).toEqual(accountId);
    });

    it('derives the ingestion and dlq locations of the business', () => {
        const configuration = new DatastoreAccessInformation({ accountId, businessID } as DatastoreAccessInformation);

        expect(configuration.ingestion).toEqual(`s3://paigo-usage-record-dump-bucket/${businessID}`);
        expect(configuration.dlq).toEqual(`s3://paigo-usage-record-dlq-bucket/${businessID}`);
    });

    it('honors the provided platform and region', () => {
        const configuration = new DatastoreAccessInformation({
            accountId,
            businessID,
            platform: SupportedDatastores.s3,
            region: 'eu-west-1',
        } as DatastoreAccessInformation);

        expect(configuration.platform).toEqual(SupportedDatastores.s3);
        expect(configuration.region).toEqual('eu-west-1');
    });

    it('provisions a uniquely named role and policy scoped to the business prefixes', async () => {
        const measurementConfigEntity = new MeasurementConfigEntity({
            measurementId: 'de388932-a7e1-11ed-afa1-0242ac120002',
            measurementMode: measurementMode.datastoreBased,
            measurementConfiguration: { accountId } as DatastoreAccessInformation,
            businessID,
        } as MeasurementConfigEntity);

        await MeasurementConfigEntity.setupAccessIfRequired(measurementConfigEntity);

        const configuration = measurementConfigEntity.measurementConfiguration as DatastoreAccessInformation;
        const [createRoleCall] = iamMock.commandCalls(CreateRoleCommand);
        const [createPolicyCall] = iamMock.commandCalls(CreatePolicyCommand);
        const [attachCall] = iamMock.commandCalls(AttachRolePolicyCommand);

        const { RoleName, AssumeRolePolicyDocument } = createRoleCall.args[0].input;
        const { PolicyName, PolicyDocument } = createPolicyCall.args[0].input;

        // Unique per measurement
        expect(RoleName).toContain('de388932-a7e1-11ed-afa1-0242ac120002');
        expect(PolicyName).toContain('de388932-a7e1-11ed-afa1-0242ac120002');
        expect(RoleName.length).toBeLessThanOrEqual(64);
        expect(PolicyName.length).toBeLessThanOrEqual(64);
        expect(attachCall.args[0].input.RoleName).toEqual(RoleName);

        // The customer account is trusted with a fresh external ID
        const trust = JSON.parse(AssumeRolePolicyDocument);
        expect(trust.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${accountId}:root`);
        expect(trust.Statement[0].Action).toEqual('sts:AssumeRole');
        expect(trust.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(configuration.externalId);
        expect(configuration.externalId).toBeTruthy();

        // The permissions are scoped to the prefixes of the business
        const policy = JSON.parse(PolicyDocument);
        const resources = policy.Statement.reduce((acc, { Resource }) => acc.concat(Resource), []);
        expect(resources).toContain(`arn:aws:s3:::paigo-usage-record-dump-bucket/${businessID}/*`);
        expect(resources).toContain(`arn:aws:s3:::paigo-usage-record-dlq-bucket/${businessID}/*`);

        expect(configuration.iamRoleArn).toEqual(`arn:aws:iam::647662420899:role/${RoleName}`);
    });

    it('generates a different external ID and role for every measurement', async () => {
        const first = new DatastoreAccessInformation({ accountId, businessID } as DatastoreAccessInformation);
        const second = new DatastoreAccessInformation({ accountId, businessID } as DatastoreAccessInformation);
        await DatastoreAccessInformation.setupAccess(first);
        await DatastoreAccessInformation.setupAccess(second);

        expect(first.externalId).not.toEqual(second.externalId);
        expect(first.iamRoleArn).not.toEqual(second.iamRoleArn);
    });

    it('updates the trust of the role while preserving the role and the external ID', async () => {
        const configuration = new DatastoreAccessInformation({
            accountId,
            businessID,
            iamRoleArn: 'arn:aws:iam::647662420899:role/paigo-dev-datastore-1234',
            externalId: 'existing-external-id',
        } as DatastoreAccessInformation);

        const updated = new DatastoreAccessInformation({
            ...configuration,
            accountId: '999999999999',
        } as DatastoreAccessInformation);

        await DatastoreAccessInformation.updateAccess(updated);

        expect(iamMock.commandCalls(CreateRoleCommand)).toHaveLength(0);
        const [updateCall] = iamMock.commandCalls(UpdateAssumeRolePolicyCommand);
        expect(updateCall.args[0].input.RoleName).toEqual('paigo-dev-datastore-1234');
        const trust = JSON.parse(updateCall.args[0].input.PolicyDocument);
        expect(trust.Statement[0].Principal.AWS).toEqual('arn:aws:iam::999999999999:root');
        expect(trust.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual('existing-external-id');
        expect(updated.iamRoleArn).toEqual(configuration.iamRoleArn);
        expect(updated.externalId).toEqual('existing-external-id');
    });

    it('persists and reads back the generated configuration', () => {
        const tags = {};
        const point = {
            tag: (key, value) => {
                tags[key] = value;
                return point;
            },
            stringField: () => point,
        };
        const configuration = new DatastoreAccessInformation({
            accountId,
            businessID,
