import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { mockClient } from 'aws-sdk-client-mock';
import { Test, TestingModule } from '@nestjs/testing';
import { UsageController } from './usage.controller';
import { UsageService } from './usage.service';

const s3Mock = mockClient(S3Client);

describe('UsageController datastore based usage', () => {
    let controller: UsageController;
    const mockCreate = jest.fn();

    const validRecord = {
        timeStamp: '2023-02-08T19:24:10Z',
        applicationId: 'e8366954-6f36-47e9-8431-ac95f88b5cc7',
        dimensionId: 'da9611bd-e0f3-4c0d-a754-fda5be730872',
        recordValue: '0.87',
        metadata: { environment: 'staging' },
    };

    beforeAll(() => {
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'paigo-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'paigo-usage-record-dlq-bucket';
    });

    beforeEach(async () => {
        s3Mock.reset();
        s3Mock.on(PutObjectCommand).resolves({});
        mockCreate.mockResolvedValue({ message: 'Measurement created' });
        const module: TestingModule = await Test.createTestingModule({
            controllers: [UsageController],
        })
            .useMocker((token) => {
                if (token === UsageService) {
                    return { create: mockCreate };
                }
            })
            .compile();

        controller = module.get<UsageController>(UsageController);
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('should be defined', () => {
        expect(controller).toBeDefined();
    });

    it('sends a valid record through the usage service with the businessID of the key', async () => {
        const response = await controller.dbUsage({
            message: JSON.stringify(validRecord),
            s3Key: 'fakeBusiness/2023/02/08/record.json',
        });

        expect(mockCreate).toHaveBeenCalledWith({ ...validRecord, businessID: 'fakeBusiness' });
        expect(s3Mock.commandCalls(PutObjectCommand)).toHaveLength(0);
        expect(response).toEqual({ message: 'Measurement created' });
    });

    it('supports fully qualified source keys', async () => {
        await controller.dbUsage({
            message: JSON.stringify(validRecord),
            s3Key: 's3://paigo-usage-record-dump-bucket/fakeBusiness/2023/02/08/record.json',
        });

        expect(mockCreate).toHaveBeenCalledWith({ ...validRecord, businessID: 'fakeBusiness' });
    });

    it('writes a malformed record to the dead letter queue mirroring the source key', async () => {
        await controller.dbUsage({
            message: '{"recordValue": "0.87"',
            s3Key: 'fakeBusiness/2023/02/08/record.json',
        });

        expect(mockCreate).not.toHaveBeenCalled();
        const [putCall] = s3Mock.commandCalls(PutObjectCommand);
        const { Bucket, Key, Body } = putCall.args[0].input;
        expect(Bucket).toEqual('paigo-usage-record-dlq-bucket');
        expect(Key).toEqual('fakeBusiness/2023/02/08/record.json.message.text');
        const parsedBody = JSON.parse(`${Body}`);
        expect(parsedBody.message).toEqual('{"recordValue": "0.87"');
        expect(parsedBody.businessID).toEqual('fakeBusiness');
        expect(parsedBody.error).toBeTruthy();
        expect(parsedBody.failedAt).toBeTruthy();
    });

    it('writes a record which cannot be indexed to the dead letter queue', async () => {
        mockCreate.mockRejectedValueOnce(new Error('dimension does not exist'));

        await controller.dbUsage({
            message: JSON.stringify(validRecord),
            s3Key: 's3://paigo-usage-record-dump-bucket/fakeBusiness/record.json',
        });

        const [putCall] = s3Mock.commandCalls(PutObjectCommand);
        expect(putCall.args[0].input.Key).toEqual('fakeBusiness/record.json.message.text');
        expect(JSON.parse(`${putCall.args[0].input.Body}`).error).toEqual('dimension does not exist');
    });

    it('writes a record missing the usage information to the dead letter queue', async () => {
        await controller.dbUsage({
            message: JSON.stringify({ metadata: { environment: 'staging' } }),
            s3Key: 'fakeBusiness/record.json',
        });

        expect(mockCreate).not.toHaveBeenCalled();
        expect(s3Mock.commandCalls(PutObjectCommand)).toHaveLength(1);
    });
});

