+import { PutObjectCommand, S3, S3Client } from '@aws-sdk/client-s3';
 import { Upload } from '@aws-sdk/lib-storage';

+export const DEFAULT_AWS_REGION = 'us-east-1';
+
+/**
+ * The bucket customers write their usage records into.
+ */
+export const DEFAULT_DATASTORE_INGESTION_BUCKET = 'paigo-usage-record-dump-bucket';
+
+/**
+ * The bucket unprocessable usage records get written to.
+ */
+export const DEFAULT_DATASTORE_DLQ_BUCKET = 'paigo-usage-record-dlq-bucket';
+
+/**
+ * Suffix appended to the mirrored source key of a record which failed processing.
+ */
+export const DLQ_KEY_SUFFIX = '.message.text';
+
+export const getDatastoreIngestionBucket = (): string =>
+    process.env.DB_MEASUREMENT_BUCKET_NAME || DEFAULT_DATASTORE_INGESTION_BUCKET;
+
+export const getDatastoreDlqBucket = (): string =>
+    process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME || DEFAULT_DATASTORE_DLQ_BUCKET;
+
 export const putDocument = (document, Bucket, Key) =>
-    new Upload({ client: new S3Client({ region: 'us-east-1' }), params: { Body: document, Bucket, Key } });
+    new Upload({ client: new S3Client({ region: DEFAULT_AWS_REGION }), params: { Body: document, Bucket, Key } });
+
+/**
+ * Normalizes an S3 key so the returned value is always relative to its bucket.
+ * Keys arriving from connectors can either be fully qualified (`s3://bucket/key`,
+ * `arn:aws:s3:::bucket/key`, `bucket/key`) or already relative (`key`).
+ *
+ * @example toRelativeS3Key('s3://paigo-usage-record-dump-bucket/business/file.json') // 'business/file.json'
+ * @example toRelativeS3Key('business/file.json') // 'business/file.json'
+ */
+export const toRelativeS3Key = (s3Key: string): string => {
+    if (!s3Key) {
+        return '';
+    }
+    let key = `${s3Key}`.trim();
+    const schemes = ['s3://', 'arn:aws:s3:::', 'https://', 'http://'];
+    const matchedScheme = schemes.find((scheme) => key.toLowerCase().startsWith(scheme));
+    if (matchedScheme) {
+        key = key.slice(matchedScheme.length);
+        // The first segment of a fully qualified key is always the bucket
+        key = key.split('/').slice(1).join('/');
+    } else {
+        key = key.replace(/^\/+/, '');
+        // Handle the case where the bucket name is prefixed without a scheme
+        const [firstSegment, ...rest] = key.split('/');
+        if (rest.length && [getDatastoreIngestionBucket(), getDatastoreDlqBucket()].includes(firstSegment)) {
+            key = rest.join('/');
+        }
+    }
+    return key.replace(/^\/+/, '');
+};
+
+/**
+ * Writes a document to S3.
+ */
+export const putObject = async ({
+    Bucket,
+    Key,
+    Body,
+    ContentType,
+    region = DEFAULT_AWS_REGION,
+}: {
+    Bucket: string;
+    Key: string;
+    Body: string;
+    ContentType?: string;
+    region?: string;
+}) => {
+    const client = new S3({ region });
+    return client.send(new PutObjectCommand({ Bucket, Key, Body, ContentType }));
+};
+
+/**
+ * Writes a record which could not be processed to the dead letter queue.
+ * The object is stored under the mirrored source key, suffixed with `.message.text`,
+ * and holds both the failed input and the metadata of the failed processing attempt.
+ */
+export const writeToDeadLetterQueue = async ({
+    s3Key,
+    message,
+    error,
+    businessID,
+    Bucket = getDatastoreDlqBucket(),
+}: {
+    s3Key: string;
+    message?: unknown;
+    error?: unknown;
+    businessID?: string;
+    Bucket?: string;
+}) => {
+    const relativeKey = toRelativeS3Key(s3Key);
+    const Key = `${relativeKey}${DLQ_KEY_SUFFIX}`;
+    const Body = JSON.stringify({
+        message,
+        s3Key,
+        sourceKey: relativeKey,
+        businessID,
+        error: error instanceof Error ? error.message : error,
+        failedAt: new Date().toISOString(),
+    });
+    await putObject({ Bucket, Key, Body, ContentType: 'text/plain' });
+    return { Bucket, Key };
